import{_ as s}from"./chunks/10.PUTb6HuW.js";import{_ as l}from"./chunks/image1.YJCAcCic.js";import{_ as d}from"./chunks/image1.CDwWxNA4.js";import{_ as c,a as i}from"./chunks/image.DUp49IjQ.js";import{_ as g}from"./chunks/image6.CqbPoGko.js";import{_ as h,a as e,b as m,c as p}from"./chunks/image4.FCpLmD95.js";import{_ as u}from"./chunks/image15.tCW31st1.js";import{_ as f}from"./chunks/image.BikqRkQy.js";import{_,a}from"./chunks/image.DXQ6aG5l.js";import{_ as y}from"./chunks/image6.BT6bI8ah.js";import{_ as b,a as o,b as w,c as x}from"./chunks/community.D8XXOc5B.js";import{_ as v}from"./chunks/image1.DQPiWyq8.js";import{_ as S}from"./chunks/image6.Cdq5CsCC.js";import{_ as k,C as P,o as z,c as T,aj as n,E as C}from"./chunks/framework.Cwzc8Cgk.js";const q="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image1.z4U7ER2h.png",A="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image100.Fqrd5Qlo.png",R="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image101.BIAMx9oK.png",D="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image2.DxpeCYov.png",I="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image3.Dc0oOkKc.png",et=JSON.parse('{"title":"3.10 Smart Recycling Station","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Creative Building & Styling/3.10 Smart Recycling Station.md","filePath":"docs/3. Creative Building & Styling/3.10 Smart Recycling Station.md"}'),E={name:"docs/3. Creative Building & Styling/3.10 Smart Recycling Station.md"};function B(W,t,j,L,V,G){const r=P("pdf");return z(),T("div",null,[t[0]||(t[0]=n('<h1 id="_3-10-smart-recycling-station" tabindex="-1">3.10 Smart Recycling Station <a class="header-anchor" href="#_3-10-smart-recycling-station" aria-label="Permalink to &quot;3.10 Smart Recycling Station&quot;">​</a></h1><h2 id="_3-10-1-lesson-introduction" tabindex="-1">3.10.1 Lesson Introduction <a class="header-anchor" href="#_3-10-1-lesson-introduction" aria-label="Permalink to &quot;3.10.1 Lesson Introduction&quot;">​</a></h2><p>The Smart Recycling Station is an intelligent educational robotic building block model designed for automated waste sorting. The front of the model is equipped with the WonderLens vision module as its visual input, while the two sorting bins on the left and right sides use 270° block servos to tilt the loading platform and deposit items. The main chassis incorporates a dot matrix display to show category icons. The modular mechanical design ensures straightforward assembly and accessible wiring. When the camera identifies a waste classification card, the corresponding servo drives the platform to dump the material into the designated bin, while the dot matrix display synchronously outputs the sorting icon. This project delivers an automated card recognition and disposal experience, integrating AI image classification, dual-servo linkage, and visual display feedback.</p><img loading="lazy" height="1080" width="1080" src="'+s+'" class="common_img" style="width:300px;"><h2 id="_3-10-2-learning-objectives" tabindex="-1">3.10.2 Learning Objectives <a class="header-anchor" href="#_3-10-2-learning-objectives" aria-label="Permalink to &quot;3.10.2 Learning Objectives&quot;">​</a></h2><ol><li>Master image classification using the WonderLens vision module. Learn methods for reading recognition signals from waste classification cards.</li><li>Program angle control routines for dual 270° block servos on the ESP32 controller. Master graphics and text display programming on the dot matrix module.</li><li>Complete system linkage debugging across visual recognition, dual-servo tilt direction control, and dot matrix feedback to achieve synchronized operation.</li><li>Assemble the complete waste sorting model and debug the program. Develop foundational skills in building multi-servo AI visual classification projects.</li></ol><h2 id="_3-10-3-assembly-guide" tabindex="-1">3.10.3 Assembly Guide <a class="header-anchor" href="#_3-10-3-assembly-guide" aria-label="Permalink to &quot;3.10.3  Assembly Guide&quot;">​</a></h2>',7)),C(r,{src:"../../_static/shared/pdf/chapter_3/10.pdf"}),t[1]||(t[1]=n('<h2 id="_3-10-4-hardware-wiring" tabindex="-1">3.10.4 Hardware Wiring <a class="header-anchor" href="#_3-10-4-hardware-wiring" aria-label="Permalink to &quot;3.10.4 Hardware Wiring&quot;">​</a></h2><p>Connect the WonderLens vision module cable to port <strong>P1</strong> of the ESP32 controller.</p><p>Connect the dot matrix display module cable to port <strong>P5</strong> of the ESP32 controller.</p><p>Connect the left 270° building block servo cable to port <strong>S1</strong> of the ESP32 controller, ensuring the <strong>orange</strong> wire is plugged into the <strong>white</strong> pin of S1.</p><p>Connect the right 270° building block servo cable to port <strong>S2</strong> of the ESP32 controller, ensuring the <strong>orange</strong> wire is plugged into the <strong>white</strong> pin of S2.</p><p>Wiring diagram:</p><img loading="lazy" height="1220" width="1490" src="'+q+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>When using the 270° block servo for the first time, detach the gear and its attached building block components from the servo before uploading the program. Upload the lesson program to the ESP32 controller and wait for the servo to rotate to its initial home position, 135°. Once initialized, reattach the components. This step can be skipped if a servo homing routine has already been executed.</strong></p></div><img loading="lazy" height="1080" width="1080" src="'+A+'" class="common_img" style="width:300px;"><img loading="lazy" height="1080" width="1080" src="'+R+'" class="common_img" style="width:300px;"><h2 id="_3-10-5-programming" tabindex="-1">3.10.5 Programming <a class="header-anchor" href="#_3-10-5-programming" aria-label="Permalink to &quot;3.10.5 Programming&quot;">​</a></h2><h3 id="_1-program-schematic" tabindex="-1">(1) Program Schematic <a class="header-anchor" href="#_1-program-schematic" aria-label="Permalink to &quot;(1)  Program Schematic&quot;">​</a></h3><img loading="lazy" height="509" width="370" src="'+D+'" class="common_img" style="width:350px;"><h3 id="_2-adding-extensions" tabindex="-1">(2) Adding Extensions <a class="header-anchor" href="#_2-adding-extensions" aria-label="Permalink to &quot;(2) Adding Extensions&quot;">​</a></h3><ul><li>Click the <strong>Extensions</strong> button and select the <strong>WonderLens</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><ul><li>Click the <strong>Extensions</strong> button and select <strong>Dot matrix module</strong> under the <strong>Output module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+d+'" class="common_img" style="width:800px;"><h3 id="_3-core-blocks" tabindex="-1">(3) Core Blocks <a class="header-anchor" href="#_3-core-blocks" aria-label="Permalink to &quot;(3) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Function Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="303" width="408" src="'+c+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="53" width="73" src="'+i+'" class="common_img"></td><td style="text-align:left;">Compares the left value with a specified value and returns a boolean result for the greater-than condition.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="119" width="317" src="'+g+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="53" width="73" src="'+i+'" class="common_img"></td><td style="text-align:left;">Performs a logical AND operation on two boolean values and returns the result.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="41" width="173" src="'+h+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="53" width="73" src="'+e+'" class="common_img"></td><td style="text-align:left;">Creates a custom variable for data storage.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="115" width="312" src="'+m+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="53" width="73" src="'+e+'" class="common_img"></td><td style="text-align:left;">Reads the data stored in the specified custom variable.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="138" width="522" src="'+p+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="53" width="73" src="'+e+'" class="common_img"></td><td style="text-align:left;">Assigns a custom value to the specified variable.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="103" width="929" src="'+u+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="51" width="75" src="'+f+'" class="common_img"></td><td style="text-align:left;">Rotates the specified servo to the target angle within a set duration and selects the delay mode.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="114" width="251" src="'+_+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="67" width="75" src="'+a+'" class="common_img"></td><td style="text-align:left;">Adjusts the brightness of the dot matrix display to a specified level between 1 and 8.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="101" width="255" src="'+y+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="67" width="75" src="'+a+'" class="common_img"></td><td style="text-align:left;">Draws the selected graphic pattern on the dot matrix display.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="412" width="760" src="'+b+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="55" width="91" src="'+o+'" class="common_img"></td><td style="text-align:left;">Switches the AI vision operating mode of the vision module.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="117" width="432" src="'+w+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="55" width="91" src="'+o+'" class="common_img"></td><td style="text-align:left;">Refreshes the camera feed and reads recognition data for the current vision mode.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="89" width="766" src="'+v+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" height="55" width="91" src="'+o+'" class="common_img"></td><td style="text-align:left;">Extracts the classification ID with the highest confidence from the image classification recognition results.</td></tr></tbody></table><h3 id="_4-complete-program" tabindex="-1">(4) Complete Program <a class="header-anchor" href="#_4-complete-program" aria-label="Permalink to &quot;(4) Complete Program&quot;">​</a></h3><ol><li><p>Initialization: At startup, initialize the WonderLens vision module at port <strong>P1</strong> and switch its operating mode to image classification. Initialize the dot matrix module at port <strong>P5</strong> and set the brightness to 5. Set 270° block servos <strong>S1</strong> and <strong>S2</strong> to rotate to 135° with an execution duration of 800 ms, then wait for 1 s.</p></li><li><p>Main Loop: The program continuously updates and retrieves recognition results from the vision module. The classification ID with the highest confidence is stored in the variable <code>Result</code>.</p><ul><li><p>When <code>Result</code> is greater than 1 and less than or equal to 4, the dot matrix module displays a cross pattern. Servo <strong>S1</strong> rotates to 115° and holds for 2 s, then resets to 135°, and the dot matrix display clears.</p></li><li><p>When <code>Result</code> is greater than 4 and less than or equal to 7, the dot matrix module displays an up arrow. Servo <strong>S1</strong> rotates to 165° and holds for 2 s, then resets to 135°, and the dot matrix display clears.</p></li><li><p>When <code>Result</code> is greater than 7 and less than or equal to 10, the dot matrix module displays a right arrow. Servo <strong>S2</strong> rotates to 165° and holds for 2 s, then resets to 135°, and the dot matrix display clears.</p></li><li><p>When <code>Result</code> is greater than 10 and less than or equal to 13, the dot matrix module displays a wrench pattern. Servo <strong>S2</strong> rotates to 115° and holds for 2 s, then resets to 135°, and the dot matrix display clears.</p></li></ul><p>Each loop iteration pauses for 0.1 s.</p></li></ol><img loading="lazy" height="1628" width="717" src="'+I+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1gpd83ho-Cf-T1LV6VETKvwf1mI7A8Bfg?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-10-6-program-upload" tabindex="-1">3.10.6 Program Upload <a class="header-anchor" href="#_3-10-6-program-upload" aria-label="Permalink to &quot;3.10.6 Program Upload&quot;">​</a></h2><img loading="lazy" height="360" width="640" src="'+S+'" class="common_img" style="width:800px;"><h2 id="_3-10-7-expansion-and-challenge" tabindex="-1">3.10.7 Expansion and Challenge <a class="header-anchor" href="#_3-10-7-expansion-and-challenge" aria-label="Permalink to &quot;3.10.7 Expansion and Challenge&quot;">​</a></h2><p><strong>Challenge Task 1: Category RGB Indicator and Sorting Error Alert</strong></p><ol><li><p>Project Goal: Assign dedicated RGB light colors to the four waste categories. When a card is identified, illuminate the corresponding RGB color. When an unrecognized or erroneous card is presented, prompt an error correction message on the dot matrix display to reinforce correct waste sorting habits.</p></li><li><p>Implementation Strategy: Construct multi-branch conditional statements. Map each waste category to its specific servo angle, RGB indicator color, and display pattern. Add an error-handling branch that closes the bins, displays error text on the dot matrix, and flashes the RGB light as a warning.</p></li><li><p>Key Challenges: Preventing cross-category recognition confusion, synchronizing servo motion, lighting, and screen feedback, and ensuring error-handling routines do not disrupt regular classification workflows.</p></li></ol><p><strong>Challenge Task 2: Timed Automatic Bin Lid Closure</strong></p><ol><li><p>Project Goal: After identifying a waste card and opening the bin lid, maintain the open position for 5 s to allow item disposal. Once the countdown expires, automatically close the lid, turn off the RGB light, and return the dot matrix display to its standby icon.</p></li><li><p>Implementation Strategy: Introduce a timer variable to start a countdown upon detecting a valid card. Keep the lid open and the RGB light illuminated during the countdown. When the timer reaches zero, reset the servo to close the lid, extinguish the light, and switch the display back to the standby screen.</p></li><li><p>Key Challenges: Ensuring the timer routine does not block the camera from recognizing new cards, and achieving smooth, coordinated motion across dual servos, lighting, and screen updates without lag.</p></li></ol><p><strong>Challenge Task 3: Creative Applications of Image Classification</strong></p><ol><li><p>Smart Material Sorter: Retain the core image classification code, replace the bin lid servos with sorting flippers, and automatically push different materials into designated storage bins upon identification.</p></li><li><p>Educational Sorting Sign: Remove the servo mechanism and combine the camera with RGB lights and a dot matrix display. Display category text and illuminate corresponding lights upon card detection for classroom demonstrations.</p></li><li><p>Universal Adaptation Strategy: Keep the core vision classification routine unchanged and swap out the output hardware. By implementing new peripheral control blocks under the logic of triggering actions upon detection, diverse sorting projects can be created.</p></li></ol><h2 id="_3-10-8-q-a" tabindex="-1">3.10.8 Q&amp;A <a class="header-anchor" href="#_3-10-8-q-a" aria-label="Permalink to &quot;3.10.8 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: During servo wiring, the orange signal wire of the 270° block servo must connect to the white pin of the corresponding servo port. What problems occur if it is wired incorrectly?</strong></p><p><strong>Answer</strong>: The white pin of ports <strong>S1</strong> and <strong>S2</strong> is dedicated to transmitting control signals, which the 270° block servo relies on to regulate the opening and closing angles of the bin lids. If the orange signal wire connects to the power or ground pins, the controller cannot transmit angle instructions. Two primary failures occur. First, the servo on the affected side remains completely motionless, preventing the lid from opening. Second, the servo vibrates erratically and rotates uncontrollably, which can generate excessive heat and cause hardware damage. In addition, all program code designed to open the lids and reset them to the initial 135° home position becomes ineffective, disrupting the automatic sorting function.</p><p><strong>Question 2: The vision module recognizes waste cards correctly and the dot matrix display shows patterns as expected, but the servos do not move at all. What are the most common causes and troubleshooting steps?</strong></p><p><strong>Answer</strong>:</p><ol><li><p>Wiring Fault: The orange signal wires of the left and right 270° block servos are not connected to the white signal pins of ports <strong>S1</strong> and <strong>S2</strong>. Troubleshooting: Disconnect the power, then verify the three-pin sequence of both servos against the wiring diagram.</p></li><li><p>Program Fault: The angle control blocks for the 270° block servos are placed outside the conditional branch that executes upon card detection, or the initial servo homing routine was omitted. Troubleshooting: Execute the servo homing routine first. Then ensure that the angle control and delay blocks reside inside the conditional branch triggered by successful card recognition.</p></li><li><p>Hardware Damage: One or both 270° block servos are defective, or ports <strong>S1</strong> and <strong>S2</strong> on the ESP32 controller are damaged. Troubleshooting: Connect known functional servos to ports <strong>S1</strong> and <strong>S2</strong> for testing. If they still do not respond, test the servos on alternative servo ports on the controller to isolate the issue.</p></li></ol><h2 id="_3-10-9-technical-support-and-product-discussion" tabindex="-1">3.10.9 Technical Support and Product Discussion <a class="header-anchor" href="#_3-10-9-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.10.9 Technical Support and Product Discussion&quot;">​</a></h2><p>Share project ideas and connect with other makers on the <a href="https://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder community</a>:</p><a href="https://forum.hiwonder.com.cn/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+x+'" class="common_img" style="width:800px;"></a>',42))])}const ot=k(E,[["render",B]]);export{et as __pageData,ot as default};
